package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public class PublicMediaPageTest {
 @Test public void declaredSourcesAndEscapesAndJsonLd(){String html="<title>Aula &amp; Som</title><meta property='og:video' content='/media/a.mp4?x=1&amp;k=2'><video src='/media/a.mp4?x=1&amp;k=2'></video><audio><source type='audio/mpeg' src='//cdn.example.org/music'></audio><script type='application/ld+json'>{\"@type\":\"VideoObject\",\"contentUrl\":\"https://cdn.example.org/b.mp4?sig=a+b\"}</script>";PublicMediaPage p=PublicMediaPage.parse(html,"https://example.org/lesson");assertEquals("Aula & Som",p.title);assertEquals(3,p.media.size());assertEquals("https://example.org/media/a.mp4?x=1&k=2",p.media.get(0).url);assertEquals("mp3",p.media.get(1).extension);assertEquals("https://cdn.example.org/b.mp4?sig=a+b",p.media.get(2).url);}
 @Test public void credentialsLocalScriptsImagesAndManifestsAreNotCandidates(){String html="<video src='http://cdn.example.org/a.mp4'></video><video src='https://127.0.0.1/a.mp4'></video><source src='https://user:password@cdn.example.org/a.mp4'><source src='https://cdn.example.org/a.m3u8'><img src='https://cdn.example.org/poster.mp4'><script>const url='https://cdn.example.org/hidden.mp4';</script>";assertTrue(PublicMediaPage.parse(html,"https://example.org/lesson").media.isEmpty());}
 @Test public void genericPageAndAacLinksKeepKnownProviderValidation(){assertEquals("https://example.org/lesson",MediaLinks.resolve("https://example.org/lesson"));assertEquals("página pública",MediaLinks.source("https://example.org/lesson"));assertEquals("aac",MediaLinks.extension("https://cdn.example.org/audio.aac?sig=x"));assertEquals("YouTube",MediaLinks.source("https://youtu.be/aqz-KE-bpKQ"));for(String link:new String[]{"https://youtube.com/watch?v=wrong","https://www.tiktok.com/@onda/live","https://example.org/stream.mpd"})try{MediaLinks.resolve(link);fail(link);}catch(IllegalArgumentException expected){}}
 @Test public void refusesFakeMediaAndPreservesDeclaredSourceAsReferer()throws Exception{String html="<video src='/bad.mp4'></video><source src='https://cdn.example.org/good.mp4'>";PublicMediaHttp.Page page=new PublicMediaHttp.Page("https://example.org/lesson","text/html",html.getBytes(StandardCharsets.UTF_8));List<String> seen=new ArrayList<>();YoutubeDownloads.Result result=MediaDownloads.fromPublicPage(page,(url,referer)->{assertEquals(page.url,referer);seen.add(url);return new PublicMediaHttp.Page(url,"video/mp4",url.contains("bad")?"<html>login</html>".getBytes():new byte[]{0,0,0,20,'f','t','y','p','i','s','o','m'});});assertEquals(2,seen.size());assertEquals(4,result.options.size());assertTrue(result.options.get(0).original);assertEquals(page.url,result.options.get(0).referer);assertEquals("aac",result.options.get(3).extension);}
 @Test public void candidateAndProbeCountsAreBounded()throws Exception{StringBuilder html=new StringBuilder();for(int i=0;i<100;i++)html.append("<video src='https://cdn.example.org/").append(i).append(".mp4'></video>");PublicMediaPage page=PublicMediaPage.parse(html.toString(),"https://example.org/lesson");assertEquals(12,page.media.size());int[] checks={0};try{MediaDownloads.fromPublicPage(new PublicMediaHttp.Page("https://example.org/lesson","text/html",html.toString().getBytes()),(url,ref)->{checks[0]++;throw new java.io.IOException("blocked");});fail();}catch(java.io.IOException expected){}assertEquals(6,checks[0]);}
 @Test public void aacHeaderDoesNotMasqueradeAsMp3(){byte[] header={(byte)255,(byte)241,80,(byte)128,1,127,(byte)252};assertTrue(PublicMediaHttp.mediaHeader(header,"aac"));assertFalse(PublicMediaHttp.mediaHeader(header,"mp3"));}

 @Test public void nestedSchemaTypesEncodingAndLazySource(){String html="<script type='application/ld+json'>{\"@graph\":[{\"@type\":[\"Thing\",\"https://schema.org/VideoObject\"],\"encoding\":[{\"encodingFormat\":\"video/mp4\",\"contentUrl\":[\"https://cdn.example.org/signed?id=1\",{\"@id\":\"https://cdn.example.org/signed?id=2\"}]}]}]}</script><video data-src='/lazy'></video>";PublicMediaPage p=PublicMediaPage.parse(html,"https://example.org/clip");assertEquals(3,p.media.size());assertEquals("https://example.org/lazy",p.media.get(0).url);assertEquals("https://cdn.example.org/signed?id=1",p.media.get(1).url);assertEquals("mp4",p.media.get(2).extension);}
 @Test public void vevoStyleYoutubePlayersAreCanonicalAndNeverOfferedAsMp4(){String html="<iframe src='https://www.youtube-nocookie.com/embed/aqz-KE-bpKQ?rel=0'></iframe><meta property='og:video' content='https://www.youtube.com/embed/aqz-KE-bpKQ'><script type='application/ld+json'>{\"@type\":\"VideoObject\",\"embedUrl\":\"https://www.youtube.com/embed/aqz-KE-bpKQ\"}</script>";PublicMediaPage p=PublicMediaPage.parse(html,"https://www.vevo.com/clip");assertTrue(p.media.isEmpty());assertEquals(Collections.singletonList("https://www.youtube.com/watch?v=aqz-KE-bpKQ"),p.youtube);assertEquals("Vevo",MediaLinks.source("https://www.hq.vevo.com/originals"));assertFalse(MediaLinks.isVevo("https://vevo.com.evil.org/clip"));}
 @Test public void followsOneDeclaredPlayerButNeverChoosesBetweenClips()throws Exception{String one="<iframe src='https://www.youtube.com/embed/aqz-KE-bpKQ'></iframe>";int[] calls={0};YoutubeDownloads.Result r=MediaDownloads.fromPublicPage(new PublicMediaHttp.Page("https://www.vevo.com/clip","text/html",one.getBytes()),(url,ref)->{throw new AssertionError("Player page must not be probed as media");},url->{calls[0]++;assertEquals("https://www.youtube.com/watch?v=aqz-KE-bpKQ",url);return new YoutubeDownloads.Result("Clip",Collections.emptyList());});assertEquals("Clip",r.title);assertEquals(1,calls[0]);try{MediaDownloads.fromPublicPage(new PublicMediaHttp.Page("https://www.vevo.com/clip","text/html",(one+"<iframe src='https://www.youtube.com/embed/i7j0bw5TonI'></iframe>").getBytes()),(url,ref)->null,url->{throw new AssertionError("Cannot choose between clips");});fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("vários players"));}}
 @Test public void ignoresUnrelatedFramesAndJsonUrls(){String html="<meta name='twitter:player' content='https://example.org/player'><iframe src='https://youtube.com.evil.org/embed/aqz-KE-bpKQ'></iframe><script type='application/ld+json'>{\"@type\":\"ImageObject\",\"contentUrl\":\"https://cdn.example.org/a.mp4\"}</script><script>var url='https://www.youtube.com/embed/aqz-KE-bpKQ';</script>";PublicMediaPage p=PublicMediaPage.parse(html,"https://example.org/clip");assertTrue(p.youtube.isEmpty());assertTrue(p.media.isEmpty());}
 @Test public void rejectedSourcesKeepHttpCauseAndMirrorsDoNotDuplicateChoices()throws Exception{String html="<video src='/one.mp4'></video><video src='/two.mp4'></video>";PublicMediaHttp.Page page=new PublicMediaHttp.Page("https://example.org/clip","text/html",html.getBytes());try{MediaDownloads.fromPublicPage(page,(url,ref)->{throw new java.io.IOException("HTTP 403 https://cdn.example.org/secret?token=private");});fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("HTTP 403"));assertFalse(expected.getMessage().contains("token="));}YoutubeDownloads.Result r=MediaDownloads.fromPublicPage(page,(url,ref)->new PublicMediaHttp.Page("https://cdn.example.org/same.mp4","video/mp4",new byte[]{0,0,0,20,'f','t','y','p','i','s','o','m'}));assertEquals(4,r.options.size());}
}
